<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {api,openProtected} from './api'
import {renderMarkdown} from './htmlArtifacts'
import './forum.css'
type Point={id:number;name:string}
type Q={id:number;kind:string;body:string;options:string[];answer?:{values:string[]};explanation?:string;score:string;points:Point[];revision:number;active?:boolean}
type Quiz={id:number;title:string;status:string;opens_at:string;closes_at:string;answers_at:string;time_limit_minutes:number;max_attempts:number;grades_published:boolean;revision:number;rules?:{kind:string;count:number;point_id?:number}[]}
type Attempt={id:number;student_id:number;student_name?:string;quiz_id:number;number:number;status:string;paper:Q[];answers:Record<string,any>;answer_revision:number;saved_at:string|null;deadline:string;server_now:string;grading_status:string;scores?:Record<string,string|null>;feedback?:Record<string,string>;grade_revision?:number;total?:string|null;submission_basis:string;grade_history?:any[]}
const props=defineProps<{courseId:number;isTeacher:boolean}>()
const base=`courses/${props.courseId}/`
const kinds:Record<string,string>={single:'单选',multiple:'多选',boolean:'判断',blank:'填空',short:'简答'}
const quizzes=ref<Quiz[]>([]),questions=ref<Q[]>([]),points=ref<Point[]>([]),quiz=ref<Quiz|null>(null),attempts=ref<Attempt[]>([]),attempt=ref<Attempt|null>(null)
const busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),bank=ref(false),create=ref(false),questionNext=ref<number|null>(null),attemptNext=ref<number|null>(null)
const qid=ref<number|null>(null),qrev=ref(0),kind=ref('single'),body=ref(''),optionText=ref('选项 A\n选项 B'),answerText=ref('0'),explanation=ref(''),score=ref('10'),pointIds=ref<number[]>([]),active=ref(true)
const quizTitle=ref(''),opens=ref(''),closes=ref(''),answersAt=ref(''),minutes=ref(30),maxAttempts=ref(1),counts=ref<Record<string,number>>({single:1,multiple:1,boolean:1,blank:1,short:1}),rulePoint=ref('')
const localAnswers=ref<Record<string,any>>({}),saveState=ref(''),dirty=ref(false),saving=ref(false),remaining=ref(0),grade=ref<Record<string,string>>({}),feedback=ref<Record<string,string>>({}),reason=ref(''),suggestions=ref<{id:number;status:string;body:string;model:string}[]>([]),stats=ref<any>(null)
let saveTimer:ReturnType<typeof setTimeout>|undefined,ticker:ReturnType<typeof setInterval>|undefined
let lastServerNow=0,lastMonotonic=0
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function list(){quizzes.value=await api<Quiz[]>(base+'quizzes/')}
async function loadBank(page=1){const result=await api<{items:Q[];next_page:number|null}>(base+`questions/?page=${page}`);questions.value=page===1?result.items:[...questions.value,...result.items];questionNext.value=result.next_page}
async function select(q:Quiz){await run(async()=>{quiz.value=q;attempt.value=null;stats.value=null;bank.value=false;create.value=false;await loadAttempts()})}
async function loadAttempts(page=1){const data=await api<{items:Attempt[];next_page:number|null}>(`quizzes/${quiz.value!.id}/attempts/?page=${page}`);attempts.value=page===1?data.items:[...attempts.value,...data.items];attemptNext.value=data.next_page}
function edit(q?:Q){qid.value=q?.id||null;qrev.value=q?.revision||0;kind.value=q?.kind||'single';body.value=q?.body||'';optionText.value=q?.options.join('\n')||'选项 A\n选项 B';answerText.value=q?.answer?.values.join('\n')||'0';explanation.value=q?.explanation||'';score.value=q?.score||'10';pointIds.value=q?.points.map(p=>p.id)||[];active.value=q?.active!==false}
async function saveQuestion(){await run(async()=>{await api(qid.value?`questions/${qid.value}/`:base+'questions/',qid.value?'PUT':'POST',{kind:kind.value,body:body.value,options:['single','multiple'].includes(kind.value)?optionText.value.split('\n').filter(x=>x.trim()):[],answer:{values:answerText.value.split('\n').filter(x=>x.trim())},explanation:explanation.value,score:score.value,point_ids:pointIds.value,active:active.value,expected_revision:qrev.value});edit();await loadBank();notice.value='题目已保存，已开始的试卷保持原快照'})}
async function createQuiz(){await run(async()=>{await api(base+'quizzes/','POST',{title:quizTitle.value,opens_at:new Date(opens.value).toISOString(),closes_at:new Date(closes.value).toISOString(),answers_at:new Date(answersAt.value).toISOString(),time_limit_minutes:minutes.value,max_attempts:maxAttempts.value,rules:Object.keys(kinds).filter(k=>counts.value[k]>0).map(k=>({kind:k,count:counts.value[k],...(rulePoint.value?{point_id:Number(rulePoint.value)}:{})}))});create.value=false;quizTitle.value='';await list();notice.value='测验草稿已创建，请核对后发布'})}
async function action(value:string){await run(async()=>{quiz.value=await api<Quiz>(`quizzes/${quiz.value!.id}/publish/`,'POST',{action:value});await list();await loadAttempts()})}
function setAttempt(a:Attempt){attempt.value=a;localAnswers.value=JSON.parse(JSON.stringify(a.answers));dirty.value=false;saveState.value=a.saved_at?'已恢复服务器保存的答案':'尚未保存答案';lastServerNow=Date.parse(a.server_now);lastMonotonic=performance.now();remaining.value=Math.max(0,Math.ceil((Date.parse(a.deadline)-lastServerNow)/1000));grade.value=Object.fromEntries(a.paper.map(q=>[q.id,a.scores?.[q.id]??'']));feedback.value={...(a.feedback||{})};reason.value='';suggestions.value=[]}
async function start(){await run(async()=>{const a=await api<Attempt>(`quizzes/${quiz.value!.id}/attempts/`,'POST',{});setAttempt(a)})}
async function openAttempt(id:number){await run(async()=>{setAttempt(await api<Attempt>(`quiz-attempts/${id}/`));if(props.isTeacher)suggestions.value=await api(`quiz-attempts/${id}/suggestion/`)})}
function changed(){dirty.value=true;saveState.value='有未保存修改';if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>void save(),800)}
async function save(){if(!attempt.value||props.isTeacher||!dirty.value||saving.value||attempt.value.status!=='in_progress')return;saving.value=true;const a=attempt.value;const answers=JSON.parse(JSON.stringify(localAnswers.value));saveState.value='正在保存…';try{const result=await api<{answer_revision:number;saved_at:string}>(`quiz-attempts/${a.id}/answers/`,'PUT',{answers,expected_revision:a.answer_revision,key:crypto.randomUUID()});if(attempt.value?.id!==a.id)return;a.answer_revision=result.answer_revision;a.saved_at=result.saved_at;dirty.value=JSON.stringify(localAnswers.value)!==JSON.stringify(answers);saveState.value=dirty.value?'有新的未保存修改':'已保存到服务器';if(dirty.value)saveTimer=setTimeout(()=>void save(),500)}catch(e){saveState.value='保存失败：'+(e instanceof Error?e.message:'请检查网络');error.value=saveState.value}finally{saving.value=false}}
async function submit(){await run(async()=>{await save();if(dirty.value)throw new Error('仍有未保存答案，请先核对保存状态；如已到期将使用服务器最后保存内容');setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/submit/`,'POST',{}));await loadAttempts();notice.value='已交卷，答案不可再修改'})}
async function refreshAttempt(){await run(async()=>{if(dirty.value&&!confirm('刷新会丢弃未保存的本地修改，继续？'))return;setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/`))})}
async function upload(q:Q,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!attempt.value)return;await run(async()=>{const form=new FormData();form.append('file',file);const data=await api<{id:number}>(`quiz-attempts/${attempt.value!.id}/images/${q.id}/`,'POST',form);const answer=localAnswers.value[q.id]||{text:'',image_ids:[]};answer.image_ids=[...(answer.image_ids||[]),data.id];localAnswers.value[q.id]=answer;changed()})}
async function review(){await run(async()=>{setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/review/`,'POST',{scores:grade.value,feedback:feedback.value,reason:reason.value,expected_revision:attempt.value!.grade_revision}));await loadAttempts();notice.value='正式评分已保存，保留修订历史'})}
async function suggest(){await run(async()=>{await api(`quiz-attempts/${attempt.value!.id}/suggestion/`,'POST',{});suggestions.value=await api(`quiz-attempts/${attempt.value!.id}/suggestion/`)})}
function shortAnswer(q:Q){if(!localAnswers.value[q.id])localAnswers.value[q.id]={text:'',image_ids:[]};return localAnswers.value[q.id]}
function canLeave(){return !dirty.value||confirm('仍有未保存答案，离开会丢失本地修改。继续？')}
async function leaveAttempt(){if(!canLeave())return;if(saveTimer)clearTimeout(saveTimer);attempt.value=null;dirty.value=false;await run(()=>loadAttempts())}
function answerLabel(q:Q,value:unknown){if(value==null)return '未作答';if(q.kind==='short')return (value as {text?:string}).text||'（无文本）';if(q.kind==='multiple')return (value as string[]).map(v=>q.options[Number(v)]).join('；')||'未作答';if(q.kind==='single')return q.options[Number(value)]||'未作答';if(q.kind==='boolean')return value==='true'?'正确':'错误';return String(value)}
defineExpose({canLeave})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(async()=>{await run(async()=>{await list();points.value=await api<Point[]>(base+'forum/points/');if(props.isTeacher)await loadBank()});loading.value=false;window.addEventListener('beforeunload',beforeUnload);ticker=setInterval(()=>{const a=attempt.value;if(!a||a.status!=='in_progress')return;remaining.value=Math.max(0,Math.ceil((Date.parse(a.deadline)-lastServerNow-(performance.now()-lastMonotonic))/1000));if(!props.isTeacher&&remaining.value===0&&!busy.value){void run(async()=>{setAttempt(await api<Attempt>(`quiz-attempts/${a.id}/submit/`,'POST',{}));notice.value='已到截止时间，按服务器最后成功保存的答案交卷'})}},1000)})
onUnmounted(()=>{if(ticker)clearInterval(ticker);if(saveTimer)clearTimeout(saveTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template>
<section class="quiz-workspace forum-workspace" aria-label="测验与题库"><div class="section-head"><div><h2>测验与题库</h2><p>冻结试卷、记录保存版本，评分与发布分别确认。</p></div><div v-if="isTeacher" class="forum-actions"><button class="secondary" @click="bank=!bank;quiz=null;attempt=null;create=false">管理题库</button><button class="primary" @click="create=true;bank=false;quiz=null;attempt=null">创建测验</button></div></div>
<p v-if="loading" role="status">正在加载…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="bank&&isTeacher"><form class="forum-card forum-form" @submit.prevent="saveQuestion"><h3>{{qid?'修订题目':'新增题目'}}</h3><label>题型<select v-model="kind"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><label>题干<textarea v-model="body" required maxlength="20000" rows="4"></textarea></label><label v-if="['single','multiple'].includes(kind)">选项（每行一个，从 0 编号）<textarea v-model="optionText" rows="4"></textarea></label><label>正确答案 / 评分参考（每行一个；选择题填编号、判断填 true/false、填空填等价答案）<textarea v-model="answerText" rows="3" required></textarea></label><label>分值<input v-model="score" type="number" min="0.01" step="0.01" required></label><label>解析<textarea v-model="explanation" rows="3"></textarea></label><fieldset><legend>知识点（可在论坛教师设置中新增）</legend><label v-for="p in points" :key="p.id"><input v-model="pointIds" type="checkbox" :value="p.id">{{p.name}}</label></fieldset><label><input v-model="active" type="checkbox">启用题目</label><button class="primary" :disabled="busy">保存题目</button><button type="button" class="secondary" @click="edit()">清空编辑</button></form><article v-for="q in questions" :key="q.id" class="forum-card"><strong>{{kinds[q.kind]}} · {{q.score}} 分 · 版本 {{q.revision}} {{q.active===false?'已停用':''}}</strong><div class="markdown-body" v-html="renderMarkdown(q.body)"></div><button class="secondary" @click="edit(q)">编辑</button></article><button v-if="questionNext" class="secondary" @click="run(()=>loadBank(questionNext!))">更多题目</button></template>
<form v-else-if="create&&isTeacher" class="forum-card forum-form" @submit.prevent="createQuiz"><h3>创建随机测验</h3><label>测验标题<input v-model="quizTitle" required maxlength="200"></label><label>开放时间<input v-model="opens" type="datetime-local" required></label><label>关闭时间<input v-model="closes" type="datetime-local" required></label><label>答案解析统一公布时间（不得早于关闭）<input v-model="answersAt" type="datetime-local" required></label><label>限时（分钟）<input v-model.number="minutes" type="number" min="1" max="240" required></label><label>最大次数<input v-model.number="maxAttempts" type="number" min="1" max="10" required></label><label>取分策略：最高正式分，并列取较晚完成</label><label>按知识点抽题<select v-model="rulePoint"><option value="">全部知识点</option><option v-for="p in points" :value="p.id">{{p.name}}</option></select></label><label v-for="(name,key) in kinds" :key="key">{{name}}题数量<input v-model.number="counts[key]" type="number" min="0" max="50"></label><button class="primary" :disabled="busy">保存测验草稿</button></form>
<template v-else-if="attempt"><button class="back" @click="leaveAttempt">← 返回答卷列表</button><h3>第 {{attempt.number}} 次作答 · {{attempt.student_name||''}}</h3><p>状态：{{attempt.status==='in_progress'?'作答中':'已交卷'}} · {{attempt.grading_status==='finalized'?'评分完成':attempt.grading_status==='awaiting_review'?'待教师复核':'尚未评分'}}</p><p v-if="attempt.status==='in_progress'">剩余 {{Math.floor(remaining/60)}} 分 {{remaining%60}} 秒（服务器截止为准）</p><p v-if="!isTeacher" role="status">{{saveState}}</p><p v-if="attempt.total!=null">{{isTeacher?'正式总分':'已公开总分'}}：{{attempt.total}}</p><p v-else-if="!isTeacher&&attempt.status==='submitted'">分数尚未公开或仍待教师复核。</p><button class="secondary" :disabled="busy||saving" @click="refreshAttempt">从服务器刷新</button>
<article v-for="(q,index) in attempt.paper" :key="q.id" class="forum-card"><strong>{{index+1}}. {{kinds[q.kind]}} · {{q.score}} 分</strong><div class="markdown-body" v-html="renderMarkdown(q.body)"></div>
<template v-if="!isTeacher&&attempt.status==='in_progress'"><fieldset v-if="q.kind==='single'||q.kind==='multiple'"><label v-for="(o,i) in q.options" :key="i"><input v-if="q.kind==='single'" v-model="localAnswers[q.id]" type="radio" :name="'q'+q.id" :value="String(i)" @change="changed"><input v-else type="checkbox" :checked="(localAnswers[q.id]||[]).includes(String(i))" @change="localAnswers[q.id]=($event.target as HTMLInputElement).checked?[...(localAnswers[q.id]||[]),String(i)]:(localAnswers[q.id]||[]).filter((v:string)=>v!==String(i));changed()">{{o}}</label></fieldset><select v-else-if="q.kind==='boolean'" v-model="localAnswers[q.id]" @change="changed"><option :value="undefined">请选择</option><option value="true">正确</option><option value="false">错误</option></select><input v-else-if="q.kind==='blank'" v-model="localAnswers[q.id]" maxlength="2000" placeholder="填写答案" @input="changed"><template v-else><textarea :value="localAnswers[q.id]?.text||''" rows="5" maxlength="10000" @input="shortAnswer(q).text=($event.target as HTMLTextAreaElement).value;changed()"></textarea><label>上传手写图片（5 MB，最多 3 张作答附件）<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy||(localAnswers[q.id]?.image_ids?.length||0)>=3" @change="upload(q,$event)"></label></template></template>
<template v-else><p>作答：{{answerLabel(q,attempt.answers[q.id])}}</p></template>
<div v-if="q.kind==='short'"><button v-for="id in (localAnswers[q.id]?.image_ids||[])" :key="id" class="secondary" @click="openProtected('/api/quiz-images/'+id+'/')">查看手写图片 #{{id}}</button></div>
<div v-if="q.answer"><p>答案 / 参考：{{q.answer.values.join('；')}}</p><div class="markdown-body" v-html="renderMarkdown(q.explanation||'')"></div></div><p v-if="attempt.scores&&attempt.scores[q.id]!=null">得分：{{attempt.scores[q.id]}}</p><p v-if="attempt.feedback?.[q.id]">评语：{{attempt.feedback[q.id]}}</p><template v-if="isTeacher&&attempt.status==='submitted'"><label>正式得分<input v-model="grade[q.id]" type="number" min="0" :max="q.score" step="0.01"></label><label>教师评语<textarea v-model="feedback[q.id]" rows="2" maxlength="5000"></textarea></label></template></article>
<div v-if="!isTeacher&&attempt.status==='in_progress'" class="forum-actions"><button class="secondary" :disabled="saving||!dirty" @click="save">{{saving?'保存中…':'立即保存'}}</button><button class="primary" :disabled="busy||saving" @click="submit">保存并交卷</button></div>
<template v-if="isTeacher&&attempt.status==='submitted'"><form class="forum-card forum-form" @submit.prevent="review"><label>评分 / 改分理由<input v-model="reason" required maxlength="500"></label><button class="primary" :disabled="busy">保存正式评分</button></form><button class="secondary" :disabled="busy" @click="suggest">生成 AI 批改建议（不自动记分）</button><article v-for="s in suggestions" :key="s.id" class="forum-card"><p>{{s.status==='failed'?'建议失败':'待教师复核'}} · {{s.model}}</p><div class="markdown-body" v-html="renderMarkdown(s.body)"></div></article><details><summary>评分修订历史</summary><p v-for="h in attempt.grade_history" :key="h.revision">版本 {{h.revision}} · {{h.reason}} · {{h.created_at}}</p></details></template>
</template>
<template v-else-if="quiz"><button class="back" @click="quiz=null">← 返回测验列表</button><h3>{{quiz.title}}</h3><p>{{quiz.status==='draft'?'草稿':quiz.status==='closed'?'已关闭':'已发布'}} · 限时 {{quiz.time_limit_minutes}} 分钟 · 最多 {{quiz.max_attempts}} 次 · 取最高正式分</p><p>开放：{{new Date(quiz.opens_at).toLocaleString()}} 至 {{new Date(quiz.closes_at).toLocaleString()}}</p><p>答案公布：{{new Date(quiz.answers_at).toLocaleString()}}</p><div v-if="isTeacher" class="forum-actions"><button v-if="quiz.status==='draft'" class="primary" :disabled="busy" @click="action('publish')">校验题量并发布</button><button v-else class="secondary" :disabled="busy" @click="action('close')">关闭测验</button><button class="secondary" :disabled="busy" @click="action(quiz.grades_published?'grades_withdraw':'grades_publish')">{{quiz.grades_published?'撤回成绩公开':'发布完整成绩'}}</button><button class="secondary" @click="run(async()=>{stats=await api('quizzes/'+quiz!.id+'/statistics/')})">题目统计</button></div><button v-else class="primary" :disabled="busy" @click="start">开始 / 恢复作答</button><button class="secondary" :disabled="busy" @click="run(()=>loadAttempts())">刷新答卷</button><p v-if="!attempts.length">暂无答卷。</p><button v-for="a in attempts" :key="a.id" class="forum-card forum-post" @click="openAttempt(a.id)">{{a.student_name||'本人'}} · 第 {{a.number}} 次 · {{a.status==='submitted'?'已交卷':'作答中'}} · {{a.grading_status==='finalized'?'评分完成':'待评分'}} <span v-if="a.total!=null">{{a.total}} 分</span></button><button v-if="attemptNext" class="secondary" @click="run(()=>loadAttempts(attemptNext!))">更多答卷</button><section v-if="stats" class="forum-card"><h3>按试卷快照统计</h3><p>待复核 {{stats.pending_attempts}} 份；同快照、每人取最高正式分，并列取较晚完成；同分按学生 ID 稳定排序。</p><p v-if="!stats.groups.length">暂无完整正式评分样本。</p><div v-for="g in stats.groups" :key="g.snapshot_hash"><h4>快照 {{g.snapshot_hash.slice(0,8)}} · {{g.sample_size}} 人</h4><p v-for="q in g.questions" :key="q.question_id">题 #{{q.question_id}} · 全对率 {{(Number(q.full_correct_rate)*100).toFixed(1)}}% · 区分度 {{q.discrimination===null?'样本不足，不可计算':Number(q.discrimination).toFixed(3)}}</p></div></section></template>
<template v-else><p v-if="!loading&&!quizzes.length">暂无可见测验。</p><button v-for="q in quizzes" :key="q.id" class="forum-card forum-post" @click="select(q)"><strong>{{q.title}}</strong><small>{{q.status==='draft'?'草稿':q.status==='closed'?'已关闭':'已发布'}} · {{q.time_limit_minutes}} 分钟</small></button></template>
</section>
</template>
